'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Complex64Array = require( '@stdlib/array/complex64' );
var Float32Array = require( '@stdlib/array/float32' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var rffti = require( '@stdlib/fft/base/fftpack/float32/rffti' );
var rfftf = require( '@stdlib/fft/base/fftpack/float32/rfftf' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var hc2c = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float32'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - sequence length
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var out;
	var w;
	var r;
	var M;

	M = floor( N/2 ) + 1;
	r = uniform( N, -100.0, 100.0, options );
	w = new Float32Array( ( 2*N ) + 34 );
	rffti( N, w, 1, 0 );
	rfftf( N, r, 1, 0, w, 1, 0 );
	out = new Complex64Array( M );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var view;
		var v;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			v = hc2c( N, r, 1, 0, out, 1, 0 );
			if ( typeof v !== 'object' ) {
				b.fail( 'should return an object' );
			}
		}
		b.toc();
		view = reinterpret( v, 0 );
		if ( isnanf( view[ 0 ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var lengths;
	var opts;
	var iter;
	var N;
	var f;
	var i;

	lengths = [
		8,
		16,
		32,
		64,
		128,
		256,
		512,
		1024
	];

	iter = 1e6;

	for ( i = 0; i < lengths.length; i++ ) {
		N = lengths[ i ];
		f = createBenchmark( N );
		opts = {
			'iterations': iter
		};
		bench( format( '%s:N=%d', pkg, N ), opts, f );
		iter = floor( pow( iter, 3.0/4.0 ) );
	}
}

main();
